    name="sigmoid_cuda_ext",
    cpp_sources="",
    cuda_sources=cuda_source,
    functions=["forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """Drop‑in replacement for the reference Model using a custom CUDA kernel."""
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure input is on CUDA and fp16
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        return sigmoid_mod.forward(x)

def get_inputs():
    # match the reference shapes and dtype
